using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.MemoryMappedFiles;
using System.Security.Principal;
using System.Threading;
using System.Web.Script.Serialization;
using ThinkPadModesV3;
internal static class LabPower {
 internal static readonly Guid Eco=new Guid("961cc777-2547-4f9d-8174-7d86181b8a7a");
 [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]struct PowerStatus{public byte Ac,Flags,Percent,Reserved;public uint Life,FullLife;}
 [System.Runtime.InteropServices.DllImport("kernel32.dll",SetLastError=true)]static extern bool GetSystemPowerStatus(out PowerStatus status);
 [System.Runtime.InteropServices.DllImport("powrprof.dll")]static extern int PowerGetUserConfiguredACPowerMode(out Guid mode);
 [System.Runtime.InteropServices.DllImport("powrprof.dll")]static extern int PowerSetUserConfiguredACPowerMode(ref Guid mode);
 internal static bool OnMains(){PowerStatus s;if(!GetSystemPowerStatus(out s)||s.Ac>1)throw new IOException("Power source unavailable");return s.Ac==1;}
 internal static Guid Read(bool ac){if(!ac)throw new ArgumentException("AC only");Guid g;if(PowerGetUserConfiguredACPowerMode(out g)!=0)throw new IOException("Power mode read failed");return g;}
 internal static void Set(bool ac,Guid g){if(!ac)throw new ArgumentException("AC only");if(PowerSetUserConfiguredACPowerMode(ref g)!=0||Read(true)!=g)throw new IOException("Power mode write/readback failed");}
}
// Laboratory probe only. No installation, service, stop, disengaged, or low level.
internal static class LenovoGuardedProbe {
 static readonly Stopwatch Clock=Stopwatch.StartNew();
 [System.Runtime.InteropServices.DllImport("kernel32.dll")] static extern ulong GetTickCount64();
 static long Tick {get{return (long)GetTickCount64();}}
 static object lastTrace;static volatile Snapshot latest;static volatile string sensorError;static volatile bool done;
 static string Image {get{return typeof(LenovoGuardedProbe).Assembly.Location;}}
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static void Write(string path,object result){Atomic.Write(path,Json.Serialize(result));}
 static double Value(Snapshot s,string name){SensorValue v;if(s==null||!s.Sensors.TryGetValue(name,out v)||v.Status!="valid"||!v.Value.HasValue)throw new IOException("Sensor unavailable: "+name);double age=(DateTime.UtcNow-DateTime.Parse(v.AcquiredUtc).ToUniversalTime()).TotalMilliseconds;if(age<0||age>4500)throw new IOException("Stale sensor: "+name);return v.Value.Value;}
 static object Thermal(bool idle){Snapshot s=latest;if(sensorError!=null)throw new IOException(sensorError);double cpu=Math.Max(Value(s,"CpuPackage"),Value(s,"CpuPackageMsr")),gpu=Value(s,"GpuTemperature"),watts=Value(s,"CpuWatts");if(cpu>=(idle?65:80)||gpu>=(idle?60:72)||(idle&&watts>=15))throw new IOException("Thermal gate: CPU="+cpu+" GPU="+gpu+" W="+watts);return new{Cpu=cpu,Gpu=gpu,CpuWatts=watts};}
 static void StartSensors(){new Thread(()=>{while(!done){try{Reply r=PipeClient.Send("status");if(!r.Ok)throw new IOException(r.Error);latest=r.Snapshot;sensorError=null;}catch(Exception e){sensorError=e.Message;}Thread.Sleep(200);}}){IsBackground=true}.Start();}
 static object Fans(LenovoOemTransport ec){int? a=null,b=null;byte ma=0,mb=0;try{ec.Select(false);ma=ec.Read(0x2F);a=ec.Rpm();ec.Select(true);mb=ec.Read(0x2F);b=ec.Rpm();}finally{ec.Select(false);}if(!a.HasValue||!b.HasValue||a<=0||b<=0)throw new IOException("Missing/nonpositive fan RPM");return new{Fan1=a,Fan2=b,Mode1=ma,Mode2=mb,UTC=DateTime.UtcNow.ToString("o")};}
 static object SetBoth(byte mode){using(var ec=new LenovoOemTransport(true)){try{try{ec.Select(false);ec.SetMode(mode);ec.Select(true);ec.SetMode(mode);}finally{ec.Select(false);}return Fans(ec);}catch{lastTrace=ec.Trace.ToArray();throw;}}}
 static object SetGlobal(byte mode){using(var ec=new LenovoOemTransport(true)){ec.SetBothOem(mode);return new{Mode=mode,Banks="OEM31=0 then1; selector0 restored",UTC=DateTime.UtcNow.ToString("o")};}}
 static void KillSdk(MemoryMappedViewAccessor view){int pid=(int)view.ReadInt64(32);if(pid<=0)return;using(var p=Process.GetProcessById(pid)){if(p.HasExited)return;string path=p.MainModule.FileName;string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),@"Lenovo\Lenovo Diagnostics Evolution")+Path.DirectorySeparatorChar;if(!Path.GetFullPath(path).StartsWith(root,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(path).StartsWith("ThinkPadModes-LsdkReadProbe-",StringComparison.Ordinal)||Digest.Of(path)!=Digest.Of(Image))throw new IOException("SDK worker identity differs");p.Kill();p.WaitForExit();}}
 static bool RecoverOwnedReadMutex(){using(var m=new Mutex(false,@"Global\Access_EC")){bool held=false,abandoned=false;try{try{held=m.WaitOne(2000);}catch(AbandonedMutexException){held=true;abandoned=true;}if(!held)throw new IOException("Owned reader mutex remains busy");return abandoned;}finally{if(held)m.ReleaseMutex();}}}
 static object ReadBoth(){using(var ec=new LenovoOemTransport(false)){try{return Fans(ec);}catch{lastTrace=ec.Trace.ToArray();throw;}}}
 static void GuardFresh(MemoryMappedViewAccessor view,Process parent){long age=Tick-view.ReadInt64(8);if(parent.HasExited||age<0||age>1500)throw new IOException("Independent guardian absent/stale");}
 static int Worker(string report,string name,int parentId){var rows=new List<object>();var result=new Dictionary<string,object>{{"UTC",DateTime.UtcNow.ToString("o")},{"Samples",rows},{"Level",7},{"StopAllowed",false}};int code=1;bool touched=false;int level=7;StartSensors();try{using(var parent=Process.GetProcessById(parentId))using(var mm=MemoryMappedFile.OpenExisting(name))using(var view=mm.CreateViewAccessor()){
   level=(int)view.ReadInt64(24);if(level!=1&&level!=7)throw new IOException("Level outside laboratory scope");result["Level"]=level;if(!String.Equals(parent.MainModule.FileName,Image,StringComparison.OrdinalIgnoreCase))throw new IOException("Guardian image differs");
   long start=Tick;while(latest==null&&Tick-start<4000){GuardFresh(view,parent);view.Write(0,Tick);Thread.Sleep(50);}Thermal(true);GuardFresh(view,parent);
   // Prove the OEM Auto write and readback before any manual setpoint.
   touched=true;rows.Add(new{Phase="Auto-before",Fans=SetBoth(0x80),Thermal=Thermal(true)});Write(report,result);
   for(int i=0;i<30;i++){GuardFresh(view,parent);Thermal(false);view.Write(0,Tick);Thread.Sleep(100);}
   GuardFresh(view,parent);Thermal(true);rows.Add(new{Phase="Level"+level+"-command",Fans=SetBoth((byte)level)});view.Write(16,2L);view.Write(0,Tick);Write(report,result);
   for(int i=0;i<(level==1?40:20);i++){GuardFresh(view,parent);object t=Thermal(false);if(level==1&&(Math.Max(Value(latest,"CpuPackage"),Value(latest,"CpuPackageMsr"))>=75||Value(latest,"CpuWatts")>=20))throw new IOException("Low-test CPU guard75C/20W");rows.Add(new{Phase="Level"+level+"-sample",Fans=ReadBoth(),Thermal=t});view.Write(0,Tick);Write(report,result);Thread.Sleep(500);}
   result["Success"]=true;code=0;
  }}catch(Exception e){result["Success"]=false;result["Error"]=e.Message;result["FailureTrace"]=lastTrace;}finally{if(touched){try{result["FinalAutomatic"]=SetBoth(0x80);result["AutomaticRestored"]=true;}catch(Exception e){result["AutomaticRestored"]=false;result["RecoveryError"]=e.Message;code=1;}}done=true;Write(report,result);}return code;}
 public static int Main(string[] args){if(args.Length==2&&(args[0]=="--elevate"||args[0]=="--elevate-crash"||args[0]=="--elevate-low"||args[0]=="--elevate-sdk-control")){string report=Path.GetFullPath(args[1]);try{var child=Process.Start(new ProcessStartInfo(Image,(args[0]=="--elevate-sdk-control"?"--guard-sdk ":args[0]=="--elevate-crash"?"--guard-crash ":args[0]=="--elevate-low"?"--guard-low ":"--guard ")+"\""+report+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden});child.WaitForExit();Write(report+".launcher.json",new{UTC=DateTime.UtcNow.ToString("o"),ExitCode=child.ExitCode});return child.ExitCode;}catch(Exception e){Write(report+".launcher.json",new{Error=e.Message});return 1;}}
  if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 77;
  if(args.Length==4&&args[0]=="--worker")return Worker(args[1],args[2],Int32.Parse(args[3]));
  if(args.Length!=2||(args[0]!="--guard"&&args[0]!="--guard-crash"&&args[0]!="--guard-low"&&args[0]!="--guard-sdk"&&args[0]!="--guard-sdk-low"&&args[0]!="--guard-sdk-crash"))return 64;bool crashTest=args[0]=="--guard-crash"||args[0]=="--guard-sdk-crash",lowTest=args[0]=="--guard-low"||args[0]=="--guard-sdk-low",sdkTest=args[0]=="--guard-sdk"||args[0]=="--guard-sdk-low"||args[0]=="--guard-sdk-crash";string path=Path.GetFullPath(args[1]);if(File.Exists(path))return 75;
  var outcome=new Dictionary<string,object>{{"UTC",DateTime.UtcNow.ToString("o")},{"StopAllowed",false},{"LowAllowed",lowTest},{"ProductionQualified",false}};MemoryMappedViewAccessor sdkView=null;Process worker=null;bool launched=false,powerChanged=false;Guid powerBefore=Guid.Empty;int exit=1;
  try{LenovoOemTransport.Verify();StartSensors();long start=Tick;while(latest==null&&sensorError==null&&Tick-start<4000)Thread.Sleep(50);if(!LabPower.OnMains())throw new IOException("AC-only laboratory test");powerBefore=LabPower.Read(true);powerChanged=true;LabPower.Set(true,LabPower.Eco);outcome["PowerBefore"]=powerBefore.ToString();for(int warm=0;warm<80;warm++)Thread.Sleep(100);outcome["IdlePreflight"]=Thermal(true);string name="Local\\ThinkPadModes.Lab."+Guid.NewGuid().ToString("N");using(var mm=MemoryMappedFile.CreateNew(name,128))using(var view=mm.CreateViewAccessor()){
    view.Write(0,Tick);view.Write(8,Tick);view.Write(24,lowTest?1L:7L);sdkView=sdkTest?mm.CreateViewAccessor():null;worker=Process.Start(new ProcessStartInfo(Image,(sdkTest?"--sdk-colocate-guarded ":"--worker ")+"\""+path+".worker.json\" "+name+" "+Process.GetCurrentProcess().Id){UseShellExecute=false,CreateNoWindow=true});launched=true;long deadline=Tick+(sdkTest?120000:35000),armedAt=0;bool deliberatelyKilled=false;
    while(!worker.HasExited){view.Write(40,Math.Max(Value(latest,"CpuPackage"),Value(latest,"CpuPackageMsr")));view.Write(48,Value(latest,"GpuTemperature"));view.Write(56,Value(latest,"CpuWatts"));view.Write(8,Tick);if(!LabPower.OnMains())throw new IOException("Power source changed");Thermal(false);if((lowTest||crashTest)&&(Math.Max(Value(latest,"CpuPackage"),Value(latest,"CpuPackageMsr"))>=75||Value(latest,"CpuWatts")>=20))throw new IOException("Low-test CPU guard75C/20W");if(crashTest&&view.ReadInt64(16)==2){if(armedAt==0)armedAt=Tick;if(Tick-armedAt>=3000&&Math.Max(Value(latest,"CpuPackage"),Value(latest,"CpuPackageMsr"))<65&&Value(latest,"CpuWatts")<15&&(!sdkTest||view.ReadInt64(64)==0)){outcome["KillUTC"]=DateTime.UtcNow.ToString("o");if(sdkTest)KillSdk(view);else worker.Kill();worker.WaitForExit();deliberatelyKilled=true;outcome["ExpectedWorkerKill"]=true;break;}}long age=Tick-view.ReadInt64(0);if(((!sdkTest||view.ReadInt64(16)==2)&&(age<0||age>2500))||Tick>deadline)throw new TimeoutException("Worker heartbeat/deadline");Thread.Sleep(50);}outcome["WorkerExitCode"]=worker.ExitCode;exit=crashTest?(deliberatelyKilled?0:1):worker.ExitCode;
   }
  }catch(Exception e){outcome["Error"]=e.Message;exit=1;}finally{done=true;if(launched){if(worker!=null&&!worker.HasExited){try{if(sdkView!=null){bool interruptedRead=sdkView.ReadInt64(64)==1;try{KillSdk(sdkView);}catch(ArgumentException){}if(!worker.WaitForExit(5000))worker.Kill();if(interruptedRead)outcome["KnownOwnedReadMutexRecovered"]=RecoverOwnedReadMutex();}else worker.Kill();worker.WaitForExit();outcome["OwnWorkerTerminated"]=true;}catch(Exception e){outcome["WorkerTerminationError"]=e.Message;exit=1;}}try{outcome["GuardianAutomatic"]=sdkTest?SetGlobal(0x80):SetBoth(0x80);outcome["AutomaticRestored"]=true;}catch(Exception e){outcome["AutomaticRestored"]=false;outcome["RecoveryError"]=e.Message;exit=1;}}if(powerChanged){try{if(LabPower.Read(true)==LabPower.Eco){LabPower.Set(true,powerBefore);outcome["PowerRestored"]=LabPower.Read(true)==powerBefore;}else outcome["PowerExternalChangePreserved"]=true;}catch(Exception e){outcome["PowerRestoreError"]=e.Message;exit=1;}}outcome["Success"]=exit==0;Write(path,outcome);if(worker!=null)worker.Dispose();if(sdkView!=null)sdkView.Dispose();}return exit;
 }
}
